insert into public.subjects(id,name)
select id,name from jsonb_to_recordset('[{"id":"portugues","name":"Língua Portuguesa","short":"Português","icon":"book","color":"#687ea5","description":"Entenda a língua antes de decorar a regra."},{"id":"matematica","name":"Matemática","short":"Matemática","icon":"calculator","color":"#b48b55","description":"Do primeiro cálculo à resolução com confiança."},{"id":"logica","name":"Raciocínio Lógico","short":"R. Lógico","icon":"brain","color":"#9080ac","description":"Aprenda a reconhecer padrões e construir argumentos."},{"id":"informatica","name":"Informática","short":"Informática","icon":"monitor","color":"#548d81","description":"Conceitos essenciais para acertar com segurança."}]'::jsonb) as x(id text,name text)
on conflict(id) do update set name=excluded.name;
insert into public.topics(id,subject_id,name,concept,example,tip)
select id,subject_id,name,concept,example,tip from jsonb_to_recordset('[{"id":"regencia","subject_id":"portugues","name":"Regência verbal","concept":"Regência é a relação entre o verbo e seu complemento. Alguns verbos se ligam diretamente ao complemento; outros exigem uma preposição. Essa exigência pode mudar conforme o sentido do verbo.","example":"Quem gosta, gosta DE algo: “Gosto de estudar”. Quem obedece, obedece A alguém: “Obedeço ao professor”. Assistir, no sentido de ver, pede A na norma-padrão: “Assisti ao filme”.","tip":"Primeiro identifique o sentido do verbo. Depois pergunte: ele exige uma preposição? Não escolha a preposição apenas pelo uso informal."},{"id":"crase","subject_id":"portugues","name":"Crase","concept":"Crase é a fusão da preposição a com outro a, geralmente o artigo feminino a. O acento grave indica essa fusão. É preciso verificar se há preposição exigida e se a palavra seguinte admite artigo.","example":"“Vou à escola”: vou A + A escola. Trocando por um masculino: “Vou ao colégio”. Já “Começou a estudar” não recebe crase, pois estudar é verbo.","tip":"Teste com uma palavra masculina equivalente: a transformação em “ao” é uma pista útil, mas observe também expressões fixas e nomes de lugares."},{"id":"concordancia","subject_id":"portugues","name":"Concordância verbal","concept":"Na concordância verbal, o verbo normalmente acompanha o sujeito em pessoa e número. Localize o núcleo do sujeito antes de escolher a forma verbal.","example":"“Os alunos estudam”: o núcleo alunos está no plural. Em “A lista de exercícios chegou”, o núcleo é lista, no singular. O verbo haver com sentido de existir é impessoal: “Há vagas”.","tip":"Não confunda o nome mais perto do verbo com o núcleo do sujeito."},{"id":"pronomes","subject_id":"portugues","name":"Pronomes","concept":"Pronomes acompanham ou substituem nomes, indicando pessoas do discurso ou estabelecendo referências. Pessoais: eu, tu, ele. Possessivos: meu, seu. Demonstrativos: este, esse, aquele.","example":"Em “Ana trouxe seu caderno”, seu é possessivo. Em “O livro que li”, que retoma livro e é pronome relativo. Na norma-padrão, palavra negativa pode atrair pronome: “Não me avisaram”.","tip":"Descubra a que palavra o pronome se refere para evitar interpretações ambíguas."},{"id":"conectivos","subject_id":"portugues","name":"Conectivos e sentidos","concept":"Conectivos relacionam ideias. Podem indicar adição, oposição, causa, conclusão ou condição. A relação depende do contexto, não apenas de uma palavra isolada.","example":"“Estudou, mas errou”: oposição. “Estudou e revisou”: adição. “Se estudar, aprenderá”: condição. “Estudou; portanto, estava preparado”: conclusão.","tip":"Antes de substituir um conectivo, diga com suas palavras qual é a relação entre as orações."},{"id":"interpretacao","subject_id":"portugues","name":"Interpretação de textos","concept":"Interpretar é construir o sentido com base no texto. Informação explícita está escrita; inferência decorre de pistas. Uma opinião pessoal não se torna verdadeira apenas porque parece provável.","example":"Texto: “Mesmo com chuva, Lia caminhou até a biblioteca”. Está explícito que Lia caminhou. Pode-se inferir que a chuva não impediu a caminhada; não se pode afirmar que Lia goste de chuva.","tip":"Procure a frase que sustenta a resposta. Desconfie de alternativas com “sempre”, “nunca” ou fatos que o texto não informa."},{"id":"operacoes","subject_id":"matematica","name":"Operações fundamentais","concept":"Adição reúne quantidades; subtração calcula diferenças; multiplicação representa somas repetidas; divisão reparte ou mede quantas vezes uma quantidade cabe em outra.","example":"Uma sala com 4 fileiras de 6 carteiras tem 4 × 6 = 24 carteiras. Em uma expressão sem parênteses, multiplicações e divisões vêm antes de adições e subtrações.","tip":"Leia a pergunta e identifique a unidade. Um resultado numérico sem interpretação pode responder à pergunta errada."},{"id":"porcentagem","subject_id":"matematica","name":"Porcentagem","concept":"Porcentagem é uma razão de denominador 100. Para calcular p% de um valor, multiplique esse valor por p e divida por 100.","example":"20% de 150 = 150 × 20 ÷ 100 = 30. Com desconto de 20%, um produto de R$ 150 custa 150 − 30 = R$ 120.","tip":"Desconto é a parte retirada; preço final é o valor restante. Não confunda os dois."},{"id":"equacoes","subject_id":"matematica","name":"Equações do 1º grau","concept":"Uma equação expressa uma igualdade que contém uma incógnita. Para isolar a incógnita, faça operações equivalentes nos dois lados da igualdade.","example":"3x + 5 = 20. Subtraindo 5 dos dois lados: 3x = 15. Dividindo ambos por 3: x = 5.","tip":"Substitua a resposta na equação original para conferir se os dois lados são iguais."},{"id":"medias","subject_id":"matematica","name":"Média aritmética","concept":"A média aritmética simples é a soma dos valores dividida pela quantidade de valores. A média não precisa ser igual a nenhum dos valores observados.","example":"Notas 6, 8 e 10: média = (6 + 8 + 10) ÷ 3 = 8.","tip":"Conte a quantidade de observações, incluindo valores repetidos."},{"id":"proporcoes","subject_id":"matematica","name":"Razão e proporção","concept":"Razão compara duas grandezas por uma divisão. Em uma proporção direta, multiplicar uma grandeza por um fator multiplica a outra pelo mesmo fator.","example":"Se 2 cadernos custam R$ 12, cada caderno custa R$ 6. Então, 5 cadernos, com o mesmo preço unitário, custam R$ 30.","tip":"Antes da regra de três, verifique se a relação é direta ou inversa e se as condições permanecem iguais."},{"id":"sequencias","subject_id":"logica","name":"Sequências numéricas","concept":"Uma sequência segue uma regra de formação. Na progressão aritmética, cada termo é obtido somando a mesma diferença ao termo anterior.","example":"Em 3, 7, 11, 15, a diferença é 4. Se a regra informada é somar 4, o próximo termo é 19.","tip":"Uma lista finita pode admitir várias regras. Use a regra explicitamente dada no enunciado."},{"id":"contagem","subject_id":"logica","name":"Princípio multiplicativo","concept":"Se uma escolha tem m possibilidades e outra escolha independente tem n possibilidades, há m × n combinações possíveis.","example":"Com 3 camisetas e 2 calças, é possível formar 3 × 2 = 6 conjuntos, usando uma peça de cada tipo.","tip":"Verifique se as escolhas são independentes e se existe alguma restrição."},{"id":"proposicoes","subject_id":"logica","name":"Proposições e negação","concept":"Proposição é uma frase declarativa à qual se pode atribuir verdadeiro ou falso. A negação inverte o valor lógico. A negação de “todos” é “existe pelo menos um que não”.","example":"Negar “Todos estudaram” resulta em “Pelo menos um não estudou”. Negar “Ana estuda e trabalha” resulta em “Ana não estuda ou não trabalha”.","tip":"Na lógica usual, “ou” é inclusivo: basta uma das proposições ser verdadeira para a disjunção ser verdadeira."},{"id":"seguranca","subject_id":"informatica","name":"Segurança da informação","concept":"Confidencialidade limita quem pode acessar; integridade protege contra alterações indevidas; disponibilidade busca manter o acesso quando necessário. Phishing usa mensagens enganosas para induzir ações.","example":"Uma mensagem pede sua senha com urgência. Em vez de seguir o link, acesse o serviço pelo endereço conhecido. Autenticação em dois fatores acrescenta uma verificação ao acesso.","tip":"Backup deve ser recuperável e testado. Sincronização sozinha pode replicar exclusões e não substitui uma estratégia de backup."},{"id":"planilhas","subject_id":"informatica","name":"Planilhas eletrônicas","concept":"Uma planilha organiza dados em células, identificadas por coluna e linha. Fórmulas normalmente começam com =. Referências relativas mudam quando copiadas; referências absolutas usam $.","example":"Em uma planilha configurada em português, =SOMA(A1:A3) soma o intervalo A1 a A3. A referência $A$1 mantém coluna e linha ao copiar a fórmula.","tip":"Os nomes das funções e separadores podem variar conforme o programa e o idioma."},{"id":"internet","subject_id":"informatica","name":"Internet e navegação","concept":"Navegador é o programa usado para acessar páginas. Mecanismo de busca localiza conteúdos. HTTPS protege os dados em trânsito entre navegador e servidor, sem garantir que o conteúdo seja confiável.","example":"Firefox é navegador. Uma busca pode ser feita em um serviço de pesquisa dentro dele. Um site fraudulento também pode utilizar HTTPS.","tip":"Verifique o domínio e o contexto. O cadeado não certifica a honestidade de uma loja ou de um remetente."}]'::jsonb) as x(id text,subject_id text,name text,concept text,example text,tip text)
on conflict(id) do update set name=excluded.name,concept=excluded.concept,example=excluded.example,tip=excluded.tip;
select public.admin_import_questions('[{"id":"9c50c9228f83c71c89aece513f794364","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"O que a regência verbal estuda?","options":["A relação entre o verbo e seus complementos.","A divisão das palavras em sílabas.","A escrita correta das palavras.","A formação do plural dos nomes."],"correct_index":0,"explanation":"A regência trata da relação que o verbo estabelece com os complementos, incluindo a necessidade de preposição.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6f5bc2b483a96788256cf185b592b424","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Complete: “Eu gosto ___ estudar”.","options":["a","em","de","por"],"correct_index":2,"explanation":"O verbo gostar exige a preposição de: quem gosta, gosta de algo.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"86ab29e336f4b6b7f89b613acc348327","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Na norma-padrão, complete: “Os alunos obedeceram ___ professor”.","options":["o","ao","do","pelo"],"correct_index":1,"explanation":"Obedecer pede complemento com a preposição a. A preposição a se une ao artigo o: ao professor.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"cad868872927e45d4613c6b40b13ac4d","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Com o sentido de ver, qual construção segue a regência tradicional de assistir?","options":["Assisti o filme.","Assisti no filme.","Assisti pelo filme.","Assisti ao filme."],"correct_index":3,"explanation":"Assistir no sentido de ver é transitivo indireto na regência tradicional: assistir a. Assim, a + o filme = ao filme.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"1a508d498bbeff7098edb769339db8b4","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Em “Preciso de ajuda”, o termo “de” é:","options":["Um artigo.","Uma preposição exigida pelo verbo.","Um pronome pessoal.","Um verbo auxiliar."],"correct_index":1,"explanation":"Precisar, no sentido de necessitar, rege a preposição de.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"7af9ece6bc450f1a96360639b63c3e48","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Qual frase apresenta complemento direto, sem preposição exigida pelo verbo?","options":["Gosto de música.","Obedeço à regra.","Comprei um livro.","Preciso de tempo."],"correct_index":2,"explanation":"Comprar é transitivo direto nesse uso: quem compra, compra algo. Um livro é objeto direto.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"aab2d0b08d1106af119eec69179edc82","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Complete segundo a norma-padrão: “Prefiro estudar ___ desistir”.","options":["do que","a","de","para"],"correct_index":1,"explanation":"A construção tradicional é preferir uma coisa a outra. Aqui: prefiro estudar a desistir.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"978134dab814a037b6d5441b58d7a451","board_id":"vunesp","subject_id":"portugues","topic_id":"regencia","kind":"basic","difficulty":"iniciante","prompt":"Complete: “Ela se lembrou ___ compromisso”.","options":["o","ao","do","pelo"],"correct_index":2,"explanation":"No uso pronominal, lembrar-se rege de: lembrou-se de + o compromisso = do compromisso.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"cfe7d4712d54b61d411b3c1978f5a7e8","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em “Vou à escola”, o acento grave marca:","options":["O plural de escola.","A fusão de a + a.","A separação de duas vogais.","Uma sílaba tônica do verbo."],"correct_index":1,"explanation":"O verbo ir pede a preposição a e escola vem com artigo a: a + a = à.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3ced3b802478c237874ec25c2443802d","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual lacuna deve receber “à”?","options":["Começou ___ estudar.","Entreguei o texto ___ uma colega.","Fui ___ biblioteca.","O curso começa ___ partir de maio."],"correct_index":2,"explanation":"Ir a + a biblioteca forma à biblioteca. Não se usa crase antes de verbo, de uma nesse contexto ou em a partir de.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"5f26360aceeb5b146735a82982132e73","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Qual frase está correta?","options":["Comecei à estudar.","O aluno respondeu à lápis.","Fomos à pé.","Entreguei a carta à professora."],"correct_index":3,"explanation":"Entregar algo a alguém: a + a professora = à professora. Estudar é verbo; lápis e pé são masculinos e não recebem essa crase.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"b0990fd5ad2171836576342cc134d081","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"O teste de trocar uma palavra feminina por uma masculina pode ajudar a identificar:","options":["A fusão de preposição e artigo, se surgir “ao”.","O número de sílabas.","O tempo verbal.","O plural do substantivo."],"correct_index":0,"explanation":"Por exemplo, vou à escola corresponde a vou ao colégio. O teste é uma pista, não dispensa a análise do contexto.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"b8d79bda5ffea5ad18886aa6d559b2aa","board_id":"vunesp","subject_id":"portugues","topic_id":"crase","kind":"basic","difficulty":"iniciante","prompt":"Em qual expressão não ocorre crase?","options":["À noite.","À tarde.","À direita.","A partir de hoje."],"correct_index":3,"explanation":"A partir de contém o verbo partir. Não há artigo feminino antes desse verbo.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"9f201ad3eecb76c30b8b0356fefc5483","board_id":"vunesp","subject_id":"portugues","topic_id":"concordancia","kind":"basic","difficulty":"iniciante","prompt":"Complete: “Os candidatos ___ preparados”.","options":["está","estão","estamos","estou"],"correct_index":1,"explanation":"O sujeito os candidatos está na terceira pessoa do plural: estão.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3e53f95b2940f51bfdc1e5c8b73c4256","board_id":"vunesp","subject_id":"portugues","topic_id":"concordancia","kind":"basic","difficulty":"iniciante","prompt":"Complete: “A lista de candidatos ___ na mesa”.","options":["estão","estamos","está","estais"],"correct_index":2,"explanation":"O núcleo do sujeito é lista, singular. De candidatos é um termo que especifica lista.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"4ed6e03d3929df5a26f1ae07e94d2b92","board_id":"vunesp","subject_id":"portugues","topic_id":"concordancia","kind":"basic","difficulty":"iniciante","prompt":"Qual frase está de acordo com a norma-padrão?","options":["Haviam muitas vagas.","Havia muitas vagas.","Existia muitas vagas.","Os candidatos chegou."],"correct_index":1,"explanation":"Haver no sentido de existir é impessoal e fica no singular. Existir concordaria com vagas: existiam.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3d1603d623e994578554e58aa2cf4f5d","board_id":"vunesp","subject_id":"portugues","topic_id":"concordancia","kind":"basic","difficulty":"iniciante","prompt":"Em “As provas começaram”, qual é o núcleo do sujeito?","options":["As","começaram","provas","Não há sujeito."],"correct_index":2,"explanation":"Provas é o substantivo central do sujeito as provas. O verbo concorda com ele no plural.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"a66c08f8becc324373d0c3ba2d23a0b6","board_id":"vunesp","subject_id":"portugues","topic_id":"concordancia","kind":"basic","difficulty":"iniciante","prompt":"Complete: “Faz dois anos que ela ___”.","options":["estudam","estuda","estudamos","estudais"],"correct_index":1,"explanation":"Ela pede estuda. Na indicação de tempo decorrido, fazer é impessoal: faz dois anos.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"4d43b6b101c2e1ba059d7df3b77a7994","board_id":"vunesp","subject_id":"portugues","topic_id":"pronomes","kind":"basic","difficulty":"iniciante","prompt":"Em “Meu caderno está aqui”, “meu” é um pronome:","options":["Possessivo.","Relativo.","Indefinido.","Interrogativo."],"correct_index":0,"explanation":"Meu indica posse em relação à primeira pessoa.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"d5fb4c122dc69df325751785b5095232","board_id":"vunesp","subject_id":"portugues","topic_id":"pronomes","kind":"basic","difficulty":"iniciante","prompt":"Em “O livro que comprei é bom”, “que” retoma:","options":["bom","comprei","livro","é"],"correct_index":2,"explanation":"O pronome relativo que retoma o antecedente livro e liga as orações.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"02a89e5dcefd14c83b954e3979062052","board_id":"vunesp","subject_id":"portugues","topic_id":"pronomes","kind":"basic","difficulty":"iniciante","prompt":"Qual frase segue a colocação pronominal esperada após palavra negativa?","options":["Não avisaram-me.","Não me avisaram.","Não avisaram eu.","Não avisaram a eu."],"correct_index":1,"explanation":"A palavra não favorece a próclise: pronome antes do verbo, não me avisaram.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"f1ef3a3d789ea2d51159f11c7b1b5a2a","board_id":"vunesp","subject_id":"portugues","topic_id":"pronomes","kind":"basic","difficulty":"iniciante","prompt":"Qual palavra pode funcionar como pronome demonstrativo?","options":["aquele","rapidamente","estudar","porque"],"correct_index":0,"explanation":"Aquele indica posição ou referência em relação às pessoas do discurso.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"b893684038594e3628a9ba5e2eb92a6a","board_id":"vunesp","subject_id":"portugues","topic_id":"pronomes","kind":"basic","difficulty":"iniciante","prompt":"Em “Ela chegou cedo”, “ela” substitui ou representa:","options":["Uma ação.","Uma pessoa ou referente feminino no singular.","Uma circunstância de tempo.","Uma ligação causal."],"correct_index":1,"explanation":"Ela é pronome pessoal da terceira pessoa do singular.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"96b3f448aa152a0fe2f670666101dbdf","board_id":"vunesp","subject_id":"portugues","topic_id":"conectivos","kind":"basic","difficulty":"iniciante","prompt":"Em “Estudou, mas não passou”, “mas” indica:","options":["Adição.","Conclusão.","Oposição.","Explicação."],"correct_index":2,"explanation":"Mas introduz contraste entre estudar e não passar.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"80afe9e8e21a5ccb6f4f1c1c42cd217c","board_id":"vunesp","subject_id":"portugues","topic_id":"conectivos","kind":"basic","difficulty":"iniciante","prompt":"Em “Se chover, ficarei em casa”, “se” expressa:","options":["Condição.","Conclusão.","Adição.","Comparação."],"correct_index":0,"explanation":"A chuva é apresentada como condição para ficar em casa.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"a6e53e67ff306bd8e2fb79454d942afa","board_id":"vunesp","subject_id":"portugues","topic_id":"conectivos","kind":"basic","difficulty":"iniciante","prompt":"Complete com ideia de conclusão: “Revisou todo o conteúdo; ___, estava preparado”.","options":["porém","portanto","embora","se"],"correct_index":1,"explanation":"Portanto introduz uma conclusão decorrente da informação anterior.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"67af1a26de9c49cd8f3a27da83410b36","board_id":"vunesp","subject_id":"portugues","topic_id":"conectivos","kind":"basic","difficulty":"iniciante","prompt":"Em “Leu e fez anotações”, a palavra “e” relaciona as ações por:","options":["Oposição.","Exclusão.","Condição.","Adição."],"correct_index":3,"explanation":"Nesse contexto, e acrescenta uma ação à outra.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"ce961c4ba6f4e0a8fcf211380c00e361","board_id":"vunesp","subject_id":"portugues","topic_id":"conectivos","kind":"basic","difficulty":"iniciante","prompt":"Em “Não saiu porque estava doente”, a segunda oração expressa:","options":["Causa.","Conclusão.","Alternância.","Finalidade."],"correct_index":0,"explanation":"Estar doente é apresentado como causa de não sair.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"f1fa2a1252a336cbf06c699cbed1069e","board_id":"vunesp","subject_id":"portugues","topic_id":"interpretacao","kind":"basic","difficulty":"iniciante","prompt":"Leia: “Mesmo com chuva, Lia caminhou até a biblioteca”. Qual informação é explícita?","options":["Lia gosta de chuva.","Lia caminhou até a biblioteca.","A biblioteca estava fechada.","Lia comprou um livro."],"correct_index":1,"explanation":"O texto afirma a caminhada até a biblioteca. As outras informações não são fornecidas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"64bdb9a8704e9826ab157413a6ec282a","board_id":"vunesp","subject_id":"portugues","topic_id":"interpretacao","kind":"basic","difficulty":"iniciante","prompt":"Leia: “Pedro voltou a estudar”. O verbo “voltou” permite inferir que:","options":["Pedro nunca estudou.","Pedro já havia estudado antes.","Pedro foi aprovado.","Pedro não gosta de estudar."],"correct_index":1,"explanation":"Voltar a fazer algo pressupõe uma ocorrência anterior. Não permite concluir aprovação ou preferências.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"bdeb91c3ede724fdf4e859f35adaa531","board_id":"vunesp","subject_id":"portugues","topic_id":"interpretacao","kind":"basic","difficulty":"iniciante","prompt":"Leia: “Alguns alunos chegaram cedo”. Qual conclusão é garantida?","options":["Todos chegaram cedo.","Ninguém chegou cedo.","Pelo menos um aluno chegou cedo.","Todos chegaram atrasados."],"correct_index":2,"explanation":"Alguns afirma a existência de alunos que chegaram cedo, sem afirmar que todos o fizeram.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"7c2cea93094244749e3e85adefcc25db","board_id":"vunesp","subject_id":"portugues","topic_id":"interpretacao","kind":"basic","difficulty":"iniciante","prompt":"Uma inferência adequada deve:","options":["Ser sustentada por pistas do texto.","Repetir uma opinião pessoal.","Adicionar qualquer fato provável.","Ignorar o contexto."],"correct_index":0,"explanation":"Inferências se apoiam em elementos textuais e relações justificáveis.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"e6e43bd883c0ec669af3ea5985c04957","board_id":"vunesp","subject_id":"portugues","topic_id":"interpretacao","kind":"basic","difficulty":"iniciante","prompt":"Leia: “A biblioteca fecha às 18 horas”. Qual alternativa extrapola o texto?","options":["A biblioteca tem um horário de fechamento.","O fechamento informado é às 18 horas.","O texto informa quando a biblioteca fecha.","A biblioteca abre às 8 horas."],"correct_index":3,"explanation":"O horário de abertura não foi informado.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6d58583402f78c0d3939d75c1908fa60","board_id":"vunesp","subject_id":"logica","topic_id":"proposicoes","kind":"basic","difficulty":"iniciante","prompt":"Qual frase é uma proposição?","options":["Feche a porta!","Que horas são?","O número 4 é par.","Estude mais!"],"correct_index":2,"explanation":"O número 4 é par é uma afirmação à qual se atribui verdadeiro ou falso. Ordens e perguntas não são proposições nesse sentido.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"adea48205417895aabdd437baba52496","board_id":"vunesp","subject_id":"logica","topic_id":"proposicoes","kind":"basic","difficulty":"iniciante","prompt":"Qual é a negação de “Todos os alunos estudaram”?","options":["Nenhum aluno estudou.","Pelo menos um aluno não estudou.","Todos os alunos não estudaram.","Pelo menos um aluno estudou."],"correct_index":1,"explanation":"Para negar uma afirmação universal, basta existir um contraexemplo.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"7abb63f81a86cfe7919acd23149733ff","board_id":"vunesp","subject_id":"logica","topic_id":"proposicoes","kind":"basic","difficulty":"iniciante","prompt":"Se P é verdadeira e Q é falsa, P e Q é:","options":["Verdadeira.","Falsa.","Impossível de avaliar.","Verdadeira e falsa."],"correct_index":1,"explanation":"A conjunção só é verdadeira quando ambas as proposições são verdadeiras.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"610c0600e77c50d6580bc865c7366260","board_id":"vunesp","subject_id":"logica","topic_id":"proposicoes","kind":"basic","difficulty":"iniciante","prompt":"Se P é verdadeira e Q é falsa, P ou Q, no sentido inclusivo, é:","options":["Falsa.","Indeterminada.","Verdadeira.","Uma pergunta."],"correct_index":2,"explanation":"Na disjunção inclusiva, basta pelo menos uma proposição verdadeira.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"055b66dc332f81ad20dddfcd86731d88","board_id":"vunesp","subject_id":"logica","topic_id":"proposicoes","kind":"basic","difficulty":"iniciante","prompt":"A negação de “Ana estuda e trabalha” é:","options":["Ana não estuda e não trabalha.","Ana não estuda ou não trabalha.","Ana estuda ou trabalha.","Ana estuda e não trabalha."],"correct_index":1,"explanation":"Pela lei de De Morgan, a negação de P e Q é não P ou não Q.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"ab9dae5963fd7d27f2411bfee02d53b7","board_id":"vunesp","subject_id":"informatica","topic_id":"seguranca","kind":"basic","difficulty":"iniciante","prompt":"Uma mensagem pede sua senha por um link urgente. A melhor atitude é:","options":["Enviar a senha para confirmar.","Clicar e informar todos os dados.","Verificar pelo canal oficial, sem usar o link suspeito.","Repassar o link aos colegas."],"correct_index":2,"explanation":"A urgência pode ser técnica de phishing. Verifique pelo serviço oficial e não entregue credenciais.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"c835d85b6836849aec83c4f91a40d8fb","board_id":"vunesp","subject_id":"informatica","topic_id":"seguranca","kind":"basic","difficulty":"iniciante","prompt":"Qual propriedade limita o acesso à informação às pessoas autorizadas?","options":["Confidencialidade.","Disponibilidade.","Velocidade.","Compressão."],"correct_index":0,"explanation":"Confidencialidade trata do acesso por pessoas autorizadas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"6242bd61785af18a1e5068d70030ba6e","board_id":"vunesp","subject_id":"informatica","topic_id":"seguranca","kind":"basic","difficulty":"iniciante","prompt":"Integridade da informação busca proteger contra:","options":["Qualquer acesso à internet.","Alterações indevidas.","A criação de cópias.","O uso de senhas."],"correct_index":1,"explanation":"Integridade significa preservar a informação contra alterações indevidas ou não detectadas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"f6860f970e2797683f95d67fde65715b","board_id":"vunesp","subject_id":"informatica","topic_id":"seguranca","kind":"basic","difficulty":"iniciante","prompt":"Qual prática melhora uma estratégia de backup?","options":["Guardar a única cópia no mesmo disco.","Nunca testar restauração.","Manter cópias e testar a recuperação.","Usar a mesma senha em tudo."],"correct_index":2,"explanation":"Uma cópia só é útil se puder ser recuperada. Separação das cópias e testes reduzem o risco.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"2b716c46cd0e0fa222d76cb312325b4a","board_id":"vunesp","subject_id":"informatica","topic_id":"seguranca","kind":"basic","difficulty":"iniciante","prompt":"O segundo fator de autenticação tem como objetivo:","options":["Eliminar qualquer risco.","Acrescentar uma verificação ao acesso.","Substituir todos os backups.","Tornar qualquer mensagem confiável."],"correct_index":1,"explanation":"O segundo fator acrescenta uma barreira. Ele não elimina todos os riscos.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"f5729d44bacf5174b27cf6d0889cb0ac","board_id":"vunesp","subject_id":"informatica","topic_id":"planilhas","kind":"basic","difficulty":"iniciante","prompt":"Qual referência mantém coluna e linha ao ser copiada?","options":["A1","$A1","A$1","$A$1"],"correct_index":3,"explanation":"O cifrão antes da coluna e da linha torna ambas absolutas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"d3f85bf1bbaee74f3926befbc6e63fee","board_id":"vunesp","subject_id":"informatica","topic_id":"planilhas","kind":"basic","difficulty":"iniciante","prompt":"Se A1 = 2, A2 = 3 e A3 = 5, qual é o resultado de =SOMA(A1:A3)?","options":["5","8","10","235"],"correct_index":2,"explanation":"O intervalo A1:A3 inclui as três células: 2 + 3 + 5 = 10.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"bfea2581a28285fda81b5b3a148389d8","board_id":"vunesp","subject_id":"informatica","topic_id":"planilhas","kind":"basic","difficulty":"iniciante","prompt":"Em uma planilha, B3 identifica:","options":["Coluna 3, linha B.","Coluna B, linha 3.","A terceira planilha.","Uma senha."],"correct_index":1,"explanation":"As letras indicam colunas; os números, linhas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"cdb3a195c10c9b95cead899458f40080","board_id":"vunesp","subject_id":"informatica","topic_id":"planilhas","kind":"basic","difficulty":"iniciante","prompt":"Ao copiar a fórmula =A1 uma linha para baixo, a referência relativa se torna:","options":["=A2","=B1","=$A$1","=A0"],"correct_index":0,"explanation":"A referência relativa acompanha o deslocamento: uma linha abaixo de A1 é A2.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"3b9935efb36878e168f5410a2e8ba843","board_id":"vunesp","subject_id":"informatica","topic_id":"planilhas","kind":"basic","difficulty":"iniciante","prompt":"Em geral, qual símbolo inicia uma fórmula em uma célula?","options":["#","@","=","!"],"correct_index":2,"explanation":"O sinal de igual informa que a célula contém uma fórmula.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"7a9b906075fc293dea3e748af273e8a1","board_id":"vunesp","subject_id":"informatica","topic_id":"internet","kind":"basic","difficulty":"iniciante","prompt":"Qual das opções é um navegador?","options":["Firefox.","Uma planilha.","Um cabo de rede.","Um arquivo PDF."],"correct_index":0,"explanation":"Firefox é um programa para navegar na web.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"957f732fe050048eb8293c18e5d99cad","board_id":"vunesp","subject_id":"informatica","topic_id":"internet","kind":"basic","difficulty":"iniciante","prompt":"O uso de HTTPS garante, por si só:","options":["Que a loja é honesta.","Que todo arquivo é seguro.","Proteção dos dados em trânsito na conexão.","Que não há propaganda."],"correct_index":2,"explanation":"HTTPS protege a conexão, mas um site fraudulento também pode usar HTTPS.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"0ffde376139f2be6a75ba14b6fee704a","board_id":"vunesp","subject_id":"informatica","topic_id":"internet","kind":"basic","difficulty":"iniciante","prompt":"Qual é a função principal de um mecanismo de busca?","options":["Localizar conteúdos a partir de uma consulta.","Trocar o processador.","Desligar a rede.","Imprimir automaticamente."],"correct_index":0,"explanation":"Mecanismos de busca indexam conteúdos e retornam resultados para consultas.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"f1c7332bf0c951dbb7ec900891a18fb2","board_id":"vunesp","subject_id":"informatica","topic_id":"internet","kind":"basic","difficulty":"iniciante","prompt":"Qual cuidado ajuda a identificar um endereço falso?","options":["Confiar somente no cadeado.","Conferir o domínio completo.","Abrir todos os anexos.","Desativar atualizações."],"correct_index":1,"explanation":"O domínio pode imitar visualmente o endereço legítimo. O cadeado sozinho não comprova legitimidade.","origin":"Autoral · curadoria inicial","editorial_status":"initial"},{"id":"4c7e29bac5a381e47f0de37b12ec2bdb","board_id":"vunesp","subject_id":"informatica","topic_id":"internet","kind":"basic","difficulty":"iniciante","prompt":"Um navegador e um mecanismo de busca são:","options":["Sempre o mesmo programa.","Conceitos distintos: o navegador acessa páginas; a busca localiza conteúdos.","Ambos peças físicas do computador.","Tipos de senha."],"correct_index":1,"explanation":"O navegador é a aplicação de acesso; a busca é um serviço que pode ser acessado nela.","origin":"Autoral · curadoria inicial","editorial_status":"initial"}]'::jsonb);
with vars as (
 select i,11+i%50 a,2+i/50 b,100+i%50 initial_stock,1+i/50 removed,
  100*(1+i%50) base,1+i/50 percent,1+i%50 x,2+i/50 coefficient,3+i%7 additive,
  30+i%50 center,1+i/50 delta,2+i%50 unit,2+i/50 quantity,
  1+i%50 first_term,1+i/50 step,2+i%50 shirts,2+i/50 pants
 from generate_series(0,1249) as s(i)
), recipes as (
 select r.* from vars cross join lateral (values
 ('operacoes',format('Uma biblioteca tinha %s livros e recebeu mais %s. Quantos livros passou a ter?',a,b),a+b,format('Some o acervo inicial aos livros recebidos: %s + %s = %s livros.',a,b,a+b),i),
 ('operacoes',format('Um estoque tinha %s cadernos. Foram retirados %s. Quantos restam?',initial_stock,removed),initial_stock-removed,format('Subtraia a retirada do estoque inicial: %s − %s = %s cadernos.',initial_stock,removed,initial_stock-removed),i+1),
 ('porcentagem',format('Calcule %s%% de %s.',percent,base),base*percent/100,format('%s%% significa %s/100. Então %s × %s ÷ 100 = %s.',percent,percent,base,percent,base*percent/100),i+2),
 ('equacoes',format('Resolva a equação %sx + %s = %s. Qual é o valor de x?',coefficient,additive,coefficient*x+additive),x,format('Subtraia %s: %sx = %s. Divida por %s: x = %s. Conferência: %s × %s + %s = %s.',additive,coefficient,coefficient*x,coefficient,x,coefficient,x,additive,coefficient*x+additive),i+3),
 ('medias',format('Qual é a média aritmética de %s, %s e %s?',center-delta,center,center+delta),center,format('Some os três valores e divida por 3: (%s + %s + %s) ÷ 3 = %s ÷ 3 = %s.',center-delta,center,center+delta,center*3,center),i),
 ('proporcoes',format('Dois cadernos custam R$ %s. Mantendo o preço unitário, quanto custam %s cadernos, em reais?',unit*2,quantity),unit*quantity,format('Cada caderno custa %s ÷ 2 = R$ %s. Portanto, %s × %s = R$ %s.',unit*2,unit,quantity,unit,unit*quantity),i+1),
 ('sequencias',format('A sequência começa em %s e soma sempre %s: %s, %s, %s, %s. Qual é o próximo termo?',first_term,step,first_term,first_term+step,first_term+2*step,first_term+3*step),first_term+4*step,format('A regra dada é somar %s. Logo, %s + %s = %s.',step,first_term+3*step,step,first_term+4*step),i+2),
 ('contagem',format('Há %s modelos de camiseta e %s modelos de calça. Quantos conjuntos diferentes podem ser formados escolhendo uma camiseta e uma calça, sem restrições?',shirts,pants),shirts*pants,format('Pelo princípio multiplicativo: %s possibilidades de camiseta × %s de calça = %s conjuntos.',shirts,pants,shirts*pants),i+3)
 ) as r(topic_id,prompt,answer,explanation,rotation)
), content as (
 select substr(encode(sha256(convert_to(r.topic_id||':'||r.prompt,'UTF8')),'hex'),1,32) id,
  t.subject_id,r.topic_id,r.prompt,r.explanation,(4-r.rotation%4)%4 correct_index,
  (select jsonb_agg(v.value::text order by (v.idx-r.rotation%4+4)%4)
    from (values (0,r.answer),(1,greatest(0,r.answer-1)),(2,r.answer+1),(3,r.answer+2)) as v(idx,value)) options
 from recipes r join public.topics t on t.id=r.topic_id
), inserted as (
 insert into public.questions(id,board_id,subject_id,topic_id,kind,difficulty,prompt,options,origin,editorial_status,generator_version,status)
 select id,'vunesp',subject_id,topic_id,'basic','iniciante',prompt,options,'Autoral · exercício parametrizado','generated','1','published' from content
 on conflict(id) do nothing returning id
)
insert into private.question_keys(question_id,correct_index,explanation)
select c.id,c.correct_index,c.explanation from content c
where c.id in (select id from inserted union select id from public.questions)
on conflict(question_id) do nothing;
commit;
